-- ============================================================
-- SEED EXT 6: Módulo 02 — Present Simple (ex 276-300) — FINAL
-- Consolidação final: PS em todas as habilidades TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-simple';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-simple não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 61: Gap fill final — contextos acadêmicos variados
  (cid,61,276,'gap_fill','The model _____ (assume) that all agents _____ (behave) rationally, a simplification that _____ (not/capture) the full complexity of human decision-making.','assumes / behave / does not capture',NULL,'PS for model assumptions and their limitations.','medium'),
  (cid,61,277,'gap_fill','Photosynthesis _____ (require) light energy, water, and carbon dioxide; it _____ (produce) glucose and oxygen.','requires / produces',NULL,'PS for biochemical processes (universal facts).','easy'),
  (cid,61,278,'gap_fill','The theory _____ (predict) that when income _____ (rise), consumption _____ (also/rise), but at a diminishing rate.','predicts / rises / also rises',NULL,'PS for economic theory statement.','medium'),
  (cid,61,279,'multiple_choice','Which sentence uses present simple MOST appropriately in a TOEFL essay thesis?','This essay contends that digital literacy constitutes a fundamental civic competency in the twenty-first century.','[''This essay contended that digital literacy constitutes a fundamental competency.'',''This essay is contending that digital literacy constitutes a fundamental competency.'',''This essay contends that digital literacy constitutes a fundamental civic competency in the twenty-first century.'',''This essay has contended that digital literacy constitutes a fundamental competency.'']','''Contends'' + ''constitutes'' = PS for thesis statement (timeless academic claim).','easy'),
  (cid,61,280,'gap_fill','The data _____ (indicate) a strong negative correlation between hours of sleep and error rates in cognitive tasks.','indicate',NULL,'''Indicate'' (PS) for reporting data findings that are still current.','easy'),

  -- BLOCK 62: Multiple choice consolidação
  (cid,62,281,'multiple_choice','Which sentence uses present simple for a GENERAL TRUTH and present perfect for a RECENT CHANGE together?','Research shows that sleep deprivation impairs cognition; recent studies have confirmed that even mild deficits produce measurable effects.','[''Research showed that sleep deprivation impaired cognition; recent studies confirmed effects.'',''Research shows that sleep deprivation impairs cognition; recent studies have confirmed that even mild deficits produce measurable effects.'',''Research is showing that sleep deprivation impairs cognition; recent studies have been confirming effects.'',''Research has shown that sleep deprivation impairs cognition; recent studies confirm that deficits produce effects.'']','PS (general truth) + PP (recent confirmation) = standard academic combination.','hard'),
  (cid,62,282,'multiple_choice','Which of these ACADEMIC REPORTING VERBS always takes present simple in formal writing?','Argue, suggest, demonstrate, show, indicate, find, note, reveal.','[''Argued, suggested, demonstrated'',''Arguing, suggesting, demonstrating'',''Argue, suggest, demonstrate, show, indicate, find, note, reveal.'',''Will argue, will suggest, will demonstrate'']','Academic reporting verbs = present simple (the texts permanently contain these arguments).','easy'),
  (cid,62,283,'multiple_choice','Which sentence INCORRECTLY uses present simple?','The author argues that economic growth is creating inequality in developing nations.','[''The author argues that economic growth increases inequality (correct).'',''The author argues that economic growth creates inequality (correct).'',''The author argues that economic growth has increased inequality (correct — PP for current relevance).'',''The author argues that economic growth is creating inequality in developing nations.'']','''Is creating'' = PC is wrong here. PS ''creates'' is the correct form with ''argues that.''','hard'),
  (cid,62,284,'gap_fill','Unlike many social phenomena, economic recessions _____ (follow) relatively predictable cycles, though the timing and depth _____ (vary) considerably.','follow / vary',NULL,'PS for patterns + PS for variation (both stable generalizations).','medium'),

  -- BLOCK 63: Production tasks — TOEFL final
  (cid,63,285,'production','[TOEFL Speaking — 45s] Explain the concept of opportunity cost and give an example. Use present simple throughout.','',NULL,'Opportunity cost is one of the most fundamental concepts in economics. It refers to the value of the next-best alternative that a person or organization gives up when making a choice. When a government spends money on a new highway, the opportunity cost includes all the other things that money could have funded — hospitals, schools, or environmental protection. At the individual level, opportunity cost operates in every decision we make: when a student chooses to study instead of working, the opportunity cost is the income they forgo. Economists argue that rational decision-making requires accounting for opportunity costs, not merely the direct financial cost of a choice. This principle helps explain why some apparently low-cost decisions turn out to be expensive once the foregone alternatives are considered.','hard'),
  (cid,63,286,'production','[TOEFL Speaking — 45s] Describe the theory of comparative advantage in international trade. Use PS for theory, literary present for Ricardo.','',NULL,'The theory of comparative advantage forms the intellectual foundation for arguments in favor of international trade. Ricardo demonstrates in his 1817 Principles of Political Economy that even if one country produces everything more efficiently than another, both countries benefit from specialization and trade. The key insight is that each country should specialize in producing the goods for which its opportunity cost is lowest — those in which it holds a comparative, rather than absolute, advantage. This principle suggests that international trade generates gains for all participants, even if the distribution of those gains is unequal. Critics note that the model relies on assumptions — full employment, factor mobility, and constant returns to scale — that frequently do not hold in the real world, and that comparative advantage says nothing about the equity of trade outcomes.','hard'),
  (cid,63,287,'production','[TOEFL Writing — 150 words] Write a conclusion for a TOEFL essay on ''Should governments limit the use of social media?'' Use present simple throughout.','',NULL,'The evidence examined in this essay suggests that the question is not whether governments should regulate social media but how comprehensively and through what mechanisms. Unregulated social media platforms demonstrably enable the spread of misinformation, facilitate psychological manipulation at scale, and provide insufficient protection to vulnerable users, particularly children. These harms do not disappear simply because the regulatory challenge is complex or because the platforms operate across national jurisdictions. At the same time, heavy-handed censorship represents a genuine threat to freedom of expression and political pluralism that democratic governments must take seriously. The most defensible approach lies between these extremes: robust transparency requirements, independent algorithmic auditing, meaningful user rights, and strict data protection standards that apply equally across all platforms. These measures protect democratic institutions and individual rights without requiring governments to determine what speech is permissible.','hard'),

  -- BLOCK 64: Gap fill avançado final
  (cid,64,288,'gap_fill','The author _____ (not/argue) that technology _____ (determine) social outcomes; rather, they _____ (contend) that social structures _____ (shape) how technology _____ (use/passive).','does not argue / determines / contend / shape / is used',NULL,'PS negative + PS positive for nuanced academic claim + PS passive.','hard'),
  (cid,64,289,'gap_fill','Behavioral economics _____ (demonstrate) that people _____ (not/always/behave) in accordance with the predictions of classical rational choice theory.','demonstrates / do not always behave',NULL,'PS for field claim + PS negative for behavioral finding.','medium'),
  (cid,64,290,'gap_fill','The first law of thermodynamics _____ (state) that energy _____ (neither/create/passive) nor _____ (destroy/passive); it _____ (simply/convert) from one form to another.','states / is neither created / destroyed / simply converts',NULL,'PS for law of physics with passive and active clauses.','hard'),

  -- BLOCK 65: Final 10 exercícios
  (cid,65,291,'multiple_choice','[Final Review] Which tense is used for a TOEFL essay thesis that presents a timeless argument?','Present simple.','[''Past simple'',''Future simple'',''Present simple.'',''Present perfect'']','Thesis = timeless academic claim → present simple.','easy'),
  (cid,65,292,'gap_fill','This study _____ (not/aim) to resolve this debate definitively; it _____ (seek) to add empirical nuance to a discussion that has so far _____ (remain/passive) largely theoretical.','does not aim / seeks / has remained',NULL,'PS negative + PS positive + PP for scope limitation.','hard'),
  (cid,65,293,'multiple_choice','[Final Review] Which sentence CORRECTLY uses present simple for a literary/philosophical claim?','Plato argues in The Republic that justice requires a correspondence between the structure of the soul and the structure of the state.','[''Plato argued in The Republic that justice required a correspondence.'',''Plato is arguing in The Republic that justice requires a correspondence.'',''Plato argues in The Republic that justice requires a correspondence between the structure of the soul and the structure of the state.'',''Plato has argued in The Republic that justice requires a correspondence.'']','Literary present: Plato perpetually ''argues'' in his text.','medium'),
  (cid,65,294,'gap_fill','The relationship between cause and effect _____ (not/operate) in isolation; multiple factors _____ (interact) simultaneously to produce any given social outcome.','does not operate / interact',NULL,'PS negative + PS plural for systems thinking in social science.','medium'),
  (cid,65,295,'production','[TOEFL Writing — short, 100 words] Write a paragraph on how the media shapes public opinion. Use PS throughout.','',NULL,'The media plays a central role in shaping public understanding of political and social issues. Through the selection and framing of stories, news organizations determine which issues receive attention and how audiences interpret them — a function that political scientists describe as agenda-setting. Research consistently shows that the topics news media cover prominently tend to be the topics that the public considers most important. In turn, the way stories are framed — which aspects are emphasized and which are ignored — influences how audiences assign responsibility and evaluate potential solutions. This process does not operate in isolation: audience pre-existing beliefs also shape how media messages are received and interpreted.','hard'),
  (cid,65,296,'production','[TOEFL Writing — short, 100 words] Write a paragraph on the concept of diminishing returns. Use PS and stative verbs.','',NULL,'The law of diminishing returns describes a fundamental principle in economics and production theory. It states that as one input into a production process is increased, holding all other inputs constant, the incremental output from each additional unit of input eventually decreases. A farmer who adds more and more fertilizer to a fixed plot of land finds that each additional kilogram of fertilizer produces a smaller increase in yield. This principle applies across many domains: a student who studies one additional hour gains less from the tenth hour than from the first. It explains why diversification in production generally makes sense and why efficiency often requires balancing multiple inputs rather than maximizing any single one.','hard'),
  (cid,65,297,'production','[TOEFL Writing — short, 100 words] Summarize the main arguments for and against nuclear energy. Use PS.','',NULL,'Nuclear energy occupies a contested position in debates about energy policy. Proponents argue that it represents one of the few energy sources capable of generating large amounts of electricity reliably without producing direct carbon emissions, making it indispensable to serious climate mitigation strategies. Critics counter that nuclear power poses unacceptable risks: the consequences of major accidents are severe and long-lasting, radioactive waste remains hazardous for thousands of years, and nuclear technology carries proliferation risks. Advocates respond that modern reactor designs are far safer than older models and that the statistical safety record of nuclear power compares favorably with fossil fuels when deaths per unit of energy produced are examined.','hard'),
  (cid,65,298,'gap_fill','Economics _____ (not/tell) us what _____ (ought/to be done); it _____ (describe) what _____ (likely/happen) under different conditions.','does not tell / ought to be done / describes / is likely to happen',NULL,'PS negative for normative limitation + PS for descriptive function of economics.','hard'),
  (cid,65,299,'multiple_choice','[Final] Which sentence is the BEST example of a TOEFL essay topic sentence using present simple?','Access to quality education determines, more than any other single factor, an individual''s long-term economic and social trajectory.','[''Access to quality education will determine an individual''s long-term trajectory.'',''Access to quality education has determined an individual''s long-term trajectory.'',''Access to quality education determines, more than any other single factor, an individual''s long-term economic and social trajectory.'',''Access to quality education is determining an individual''s long-term trajectory.'']','Topic sentence = general truth / argument → present simple.','easy'),
  (cid,65,300,'production','[TOEFL Speaking — 60s] Final production task: Discuss the concept of social capital and its relationship to economic development. Use present simple, stative verbs, and the literary present for a theorist.','',NULL,'Social capital refers to the networks, norms, and trust that enable individuals and communities to act collectively and cooperate for mutual benefit. The sociologist Robert Putnam argues in Bowling Alone that social capital has two main forms: bonding capital, which connects people within similar groups, and bridging capital, which links people across different social divides. Research consistently suggests that communities with high levels of social capital tend to have stronger economic performance, lower crime rates, better health outcomes, and more effective governance. The mechanism is straightforward: trust reduces transaction costs, networks facilitate information sharing, and norms of reciprocity support collaboration that markets alone do not generate. Conversely, economic inequality tends to erode social capital by reducing interaction between different social groups and weakening the shared institutions that facilitate collective action.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
